-- Add SigLIP, introduced in arXiv 2303.15343.
-- Added 2026-10-18 from a scan of methods named by many recent papers but
-- missing from the catalog. The source paper gets the source evidence row (Introduced banner).

INSERT INTO methods (
    slug,
    name,
    full_name,
    description,
    keywords,
    area_id,
    introduced_year,
    source_paper_id,
    source_url,
    source_title,
    code_snippet_url,
    image_url,
    image_credit
)
VALUES (
    'siglip',
    'SigLIP',
    'Sigmoid Loss for Language-Image Pre-training (SigLIP)',
    'SigLIP (Sigmoid Loss for Language-Image Pre-training) replaces the softmax-normalized contrastive loss of [CLIP](/methods/clip) with a simple pairwise sigmoid loss. Each image-text pair is treated as an independent binary classification problem, positive for matching pairs and negative otherwise, so the loss needs no global view of all pairwise similarities for normalization. This decouples the loss from the batch size: it scales to very large batches, works better at small batches, and allows a memory-efficient chunked implementation across devices. With Locked-image Tuning, a SigLiT model reached 84.5% ImageNet zero-shot accuracy after two days on four TPUv4 chips, and the authors found that gains from growing the batch size saturate around 32k. [SigLIP 2](/paper/2502.14786) (2025) extends the recipe with captioning-based pretraining, self-distillation and masked prediction, online data curation and multilingual data, improving localization and dense features. SigLIP encoders are a standard vision backbone in vision-language models and [VLA](/methods/vla) policies such as [OpenVLA](/methods/openvla).',
    'SigLIP, SigLip, siglip, sigmoid loss for language image pre-training, sigmoid loss for language-image pre-training',
    (
        SELECT id
        FROM areas
        WHERE name = 'Vision'
        LIMIT 1
    ),
    2023,
    (
        SELECT id
        FROM papers
        WHERE arxiv_id = '2303.15343'
        ORDER BY is_latest_version DESC, id DESC
        LIMIT 1
    ),
    NULL,
    'Sigmoid Loss for Language Image Pre-Training',
    'https://github.com/google-research/big_vision',
    NULL,
    '[Sigmoid Loss for Language Image Pre-Training](/paper/2303.15343)'
)
ON CONFLICT (slug) DO UPDATE
SET
    name = EXCLUDED.name,
    full_name = EXCLUDED.full_name,
    description = EXCLUDED.description,
    keywords = EXCLUDED.keywords,
    area_id = EXCLUDED.area_id,
    introduced_year = EXCLUDED.introduced_year,
    source_paper_id = EXCLUDED.source_paper_id,
    source_url = EXCLUDED.source_url,
    source_title = EXCLUDED.source_title,
    code_snippet_url = EXCLUDED.code_snippet_url,
    image_url = EXCLUDED.image_url,
    image_credit = EXCLUDED.image_credit,
    updated_at = CURRENT_TIMESTAMP;

INSERT INTO paper_methods (paper_id, method_id)
SELECT source_paper_id, id FROM methods
WHERE slug = 'siglip' AND source_paper_id IS NOT NULL
ON CONFLICT (paper_id, method_id) DO NOTHING;

INSERT INTO paper_method_evidence (paper_id, method_id, evidence_type)
SELECT source_paper_id, id, 'source' FROM methods
WHERE slug = 'siglip' AND source_paper_id IS NOT NULL
ON CONFLICT (paper_id, method_id, evidence_type) DO UPDATE SET
    last_seen_at = now();

