INSERT INTO paper_method_exclusions (paper_id, method_id, reason)
SELECT paper_id, method_id, 'siglip citation review 2026-10-18: cites the source without naming the method in title or abstract'
FROM siglip_excluded_papers
ON CONFLICT (paper_id, method_id) DO UPDATE SET
    reason = EXCLUDED.reason,
    updated_at = now();

DELETE FROM paper_methods pm
USING siglip_excluded_papers x
WHERE pm.paper_id = x.paper_id AND pm.method_id = x.method_id;

-- 76 local citers name the method in title or abstract.
CREATE TEMP TABLE siglip_cited_papers ON COMMIT DROP AS
SELECT p.id AS paper_id, m.id AS method_id
FROM papers p
CROSS JOIN methods m
WHERE m.slug = 'siglip'
  AND p.id IS DISTINCT FROM m.source_paper_id
  AND p.id IN (
        21960, 27488, 28517, 30127, 30988, 32871, 38368, 38502, 39757, 40264, 40593, 41084,
        41203, 41253, 42034, 45195, 46303, 46403, 46414, 46672, 47147, 47856, 48494, 48954,
        49717, 50785, 51450, 51567, 52074, 52108, 52207, 52666, 53453, 55319, 55447, 55525,
        56089, 56507, 57764, 60234, 60621, 63405, 63441, 63668, 63814, 64768, 65868, 66763,
        68414, 69039, 70523, 72399, 74534, 76037, 83674, 84051, 84875, 84932, 85877, 86374,
        87094, 87392, 90578, 94182, 94381, 96285, 98969, 100110, 105371, 108080, 108246, 113842,
        114011, 119515, 120843, 122607
  );

INSERT INTO paper_methods (paper_id, method_id)
SELECT paper_id, method_id FROM siglip_cited_papers x
WHERE NOT EXISTS (
    SELECT 1 FROM paper_method_exclusions e
    WHERE e.paper_id = x.paper_id AND e.method_id = x.method_id
)
ON CONFLICT (paper_id, method_id) DO NOTHING;

INSERT INTO paper_method_evidence (paper_id, method_id, evidence_type)
SELECT x.paper_id, x.method_id, 'reference' FROM siglip_cited_papers x
JOIN paper_methods pm ON pm.paper_id = x.paper_id AND pm.method_id = x.method_id
ON CONFLICT (paper_id, method_id, evidence_type) DO UPDATE SET
    last_seen_at = now();

-- 114 papers match the method keywords (same matcher as the
-- daily keyword backfill).
CREATE TEMP TABLE siglip_keyword_papers ON COMMIT DROP AS
SELECT p.id AS paper_id, m.id AS method_id
FROM papers p
CROSS JOIN methods m
WHERE m.slug = 'siglip'
  AND p.id IS DISTINCT FROM m.source_paper_id
  AND p.id IN (
        21960, 27488, 28517, 30127, 30988, 32871, 33908, 34430, 38368, 38502, 39757, 39910,
        40264, 40593, 40990, 41084, 41203, 41253, 42034, 42155, 44687, 45195, 46004, 46303,
        46403, 46414, 46672, 47147, 47856, 48494, 48616, 48954, 49717, 50785, 50828, 51450,
        51567, 51723, 51981, 52074, 52108, 52207, 52666, 52970, 53453, 54199, 54378, 54546,
        54644, 55319, 55447, 55525, 56089, 56363, 56507, 56634, 57031, 57663, 57764, 59916,
        60234, 60475, 60621, 62194, 63405, 63441, 63668, 63814, 64768, 65868, 66763, 68414,
        69039, 70523, 72399, 74534, 76037, 83018, 83493, 83674, 84011, 84051, 84760, 84875,
        84891, 84932, 85877, 86374, 87094, 87392, 90578, 93394, 94182, 94381, 96285, 97476,
        98867, 98969, 100110, 101966, 105371, 108080, 108246, 109068, 111083, 113842, 114011, 114204,
        119513, 119515, 120843, 120888, 121601, 122607
  );

INSERT INTO paper_methods (paper_id, method_id)
SELECT paper_id, method_id FROM siglip_keyword_papers x
WHERE NOT EXISTS (
    SELECT 1 FROM paper_method_exclusions e
    WHERE e.paper_id = x.paper_id AND e.method_id = x.method_id
)
ON CONFLICT (paper_id, method_id) DO NOTHING;

INSERT INTO paper_method_evidence (paper_id, method_id, evidence_type)
SELECT x.paper_id, x.method_id, 'keyword' FROM siglip_keyword_papers x
JOIN paper_methods pm ON pm.paper_id = x.paper_id AND pm.method_id = x.method_id
ON CONFLICT (paper_id, method_id, evidence_type) DO UPDATE SET
    last_seen_at = now();
